  // - CCAsset: Creative Cloud files (Photoshop, Illustrator, Premiere Pro, XD, Libraries, etc.)
  // - DCAsset: Document Cloud (Acrobat, Sign PDFs)
  // - LightroomAsset: Lightroom photos — use query only, no filters
  // - StockAsset: Adobe Stock (photos, vectors, videos, templates, 3D, etc.)
  // - GenAIAsset: Firefly-generated assets
  entityScope?: "CCAsset" | "DCAsset" | "LightroomAsset" | "StockAsset" | "GenAIAsset";
  // Optional filters. Only include keys that apply to your entityScope.
  filters?: {
  // Asset class(es): "file", "composite", or "directory". Applicable scopes: CCAsset, GenAIAsset.
  assetClass?: "file" | "composite" | "directory" | Array<"file" | "composite" | "directory">;
  // Content type. Applicable scopes: StockAsset only.
  contentType?: "Photo" | "Video" | "Vector" | "Illustration" | "Template" | "Audio" | "Animation" | "3D";
  // Directory URN(s) for recursive search within a folder. Applicable scopes: CCAsset, DCAsset.
  directoryIds?: string | Array<string>;
  // Files I can edit. Applicable scopes: CCAsset, DCAsset.
